CREATE TABLE arquivos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome_arquivo TEXT NOT NULL,
    caminho_completo TEXT NOT NULL,
    conteudo LONGTEXT,
    extensao VARCHAR(50),
    tamanho_bytes BIGINT,
    data_importacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

