CREATE TABLE tb_acampamentos_consolidado (
    id INT AUTO_INCREMENT PRIMARY KEY,
    ano INT NOT NULL,
    origem_tabela VARCHAR(100) NOT NULL,   -- rastreabilidade: de qual tabela anual veio
    razao_social VARCHAR(255),
    nome_fantasia VARCHAR(255),
    cnpj VARCHAR(20),
    porte VARCHAR(50),
    situacao VARCHAR(100),
    segmento VARCHAR(255),
    uf VARCHAR(2),
    municipio VARCHAR(255),
    data_inicio_operacao DATE,
    INDEX idx_ano (ano),
    INDEX idx_uf (uf),
    INDEX idx_municipio (municipio),
    INDEX idx_ano_uf (ano, uf)
);


SELECT municipio, ano, COUNT(id) AS total
FROM tb_acampamentos_consolidado
WHERE municipio = 'Itu'
GROUP BY municipio, ano
ORDER BY ano ASC;